import { focusRingWithin } from "@/lib/beton/shared";
import { tv, type VariantProps } from "@/lib/beton/tv";

export const slider = tv({
  slots: {
    root: "flex w-full flex-col gap-2 data-disabled:cursor-not-allowed",
    header: "flex items-center justify-between gap-4",
    label: "font-display text-sm font-bold uppercase tracking-wide text-foreground",
    value: "font-mono text-sm font-bold tabular-nums text-foreground",
    control: "relative flex w-full touch-none select-none items-center py-4",
    track: "relative w-full grow border-3 border-border bg-raised data-disabled:bg-disabled",
    indicator: "h-full bg-primary data-disabled:bg-disabled-foreground",
    thumb: [
      "relative border-3 border-border bg-raised shadow-sm",
      "after:absolute after:content-['']",
      "data-dragging:shadow-none",
      "data-disabled:border-disabled-foreground data-disabled:bg-disabled data-disabled:shadow-none",
      focusRingWithin,
    ],
  },
  variants: {
    variant: {
      primary: { indicator: "bg-primary" },
      secondary: { indicator: "bg-secondary" },
      danger: { indicator: "bg-danger" },
    },
    size: {
      sm: { track: "h-2.5", thumb: "size-5 border-2 after:-inset-3" },
      md: { track: "h-3", thumb: "size-7 after:-inset-2" },
      lg: { track: "h-4", thumb: "size-9 after:-inset-1" },
    },
  },
  defaultVariants: {
    variant: "primary",
    size: "md",
  },
});

export type SliderVariants = VariantProps<typeof slider>;

"use client";

import { Slider as BaseSlider } from "@base-ui/react/slider";
import { slider, type SliderVariants } from "@/lib/beton/recipes/slider.recipe";
import type { ReactNode } from "react";

export interface SliderProps
  extends Omit<BaseSlider.Root.Props, "className" | "children">, SliderVariants {
  className?: string;
  /** Visible label, associated with every thumb. */
  label?: ReactNode;
  /** Shows the formatted value next to the label. */
  showValue?: boolean;
  /** Accessible names for each thumb of a range slider, e.g. ["Minimum", "Maximum"]. */
  thumbLabels?: string[];
}

/** Select a value, or a range with an array value, by dragging or with the arrow keys. */
export function Slider({
  variant = "primary",
  size = "md",
  label,
  showValue = false,
  thumbLabels,
  className,
  "aria-label": ariaLabel,
  ...props
}: SliderProps) {
  const styles = slider({ variant, size });
  const current = props.value ?? props.defaultValue;
  const count = Array.isArray(current) ? current.length : 1;

  return (
    <BaseSlider.Root
      {...props}
      data-variant={variant}
      data-size={size}
      className={styles.root({ class: className })}
    >
      {label || showValue ? (
        <div className={styles.header()}>
          {label ? <BaseSlider.Label className={styles.label()}>{label}</BaseSlider.Label> : null}
          {showValue ? <BaseSlider.Value className={styles.value()} /> : null}
        </div>
      ) : null}
      <BaseSlider.Control className={styles.control()}>
        <BaseSlider.Track className={styles.track()}>
          <BaseSlider.Indicator className={styles.indicator()} />
          {Array.from({ length: count }, (_, index) => (
            <BaseSlider.Thumb
              key={index}
              index={index}
              aria-label={thumbLabels?.[index] ?? (label ? undefined : ariaLabel)}
              className={styles.thumb()}
            />
          ))}
        </BaseSlider.Track>
      </BaseSlider.Control>
    </BaseSlider.Root>
  );
}
